**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("klasa.txt");
    string nazwisko;
    int wynik;
    vector<int> wyniki;
    int suma = 0;
    while (plik >> nazwisko >> wynik) {
        wyniki.push_back(wynik);
        suma += wynik;
    }

    double srednia = (double)suma / wyniki.size();
    cout << fixed << setprecision(2);
    cout << "a) Srednia klasy: " << srednia << endl;

    int powyzej = 0, ponizej = 0;
    for (int w : wyniki) {
        if (w > srednia) powyzej++;
        else ponizej++;
    }

    cout << "b) Powyzej sredniej: " << powyzej << endl;
    cout << "c) Ponizej lub rowne sredniej: " << ponizej << endl;
    cout << "d) Procent powyzej sredniej: " << (double)powyzej * 100.0 / wyniki.size() << "%" << endl;
    return 0;
}
```

**Wyjasnienie**: Dwa przejscia: pierwsze zbiera dane i oblicza sume, drugie zlicza powyzej/ponizej. Srednia to double, wiec porownanie jest precyzyjne.

Weryfikacja:
- Suma: 78+85+92+67+73+88+91+64+55+82 = 775
- Srednia: 775/10 = 77.50
- Powyzej 77.50: 78, 85, 92, 88, 91, 82 = 6
- Ponizej lub rowne 77.50: 67, 73, 64, 55 = 4
- Procent: 6/10*100 = 60.00%
